
.shell {
  position: relative;
  overflow: hidden;
  container-type: inline-size;
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
  padding: 1rem;
  border-radius: 1.75rem;
  color: #ecf5f2;
  background:
    radial-gradient(circle at top left, rgba(66, 132, 137, 0.2), transparent 34%),
    radial-gradient(circle at top right, rgba(207, 173, 102, 0.16), transparent 32%),
    linear-gradient(155deg, rgba(5, 15, 19, 0.98), rgba(8, 24, 31, 0.96) 54%, rgba(4, 10, 15, 0.98));
  border: 1px solid rgba(131, 178, 173, 0.18);
  box-shadow: 0 1.75rem 4.5rem rgba(0, 0, 0, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.shell::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(rgba(138, 182, 177, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(138, 182, 177, 0.04) 1px, transparent 1px);
  background-size: 1.5rem 1.5rem;
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.55), transparent 95%);
}

.ambient {
  position: absolute;
  width: 18rem;
  height: 18rem;
  border-radius: 999px;
  filter: blur(1.25rem);
  opacity: 0.54;
  pointer-events: none;
}

.ambient-left {
  top: -6rem;
  left: -4rem;
  background: radial-gradient(circle, rgba(91, 171, 163, 0.28), transparent 70%);
}

.ambient-right {
  right: -5rem;
  bottom: -7rem;
  background: radial-gradient(circle, rgba(213, 177, 95, 0.2), transparent 70%);
}

.top-bar,
.main-stage,
.confirm-backdrop {
  position: relative;
  z-index: 1;
}

.top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.625rem 0.875rem;
  border-radius: 1rem;
  background: rgba(8, 18, 24, 0.74);
  border: 1px solid rgba(124, 172, 167, 0.16);
  backdrop-filter: blur(0.75rem);
}

.top-meta,
.top-pills,
.group-tabs,
.sub-tabs,
.confirm-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.top-meta span,
.top-pills span,
.chip {
  display: inline-flex;
  align-items: center;
  min-height: 1.9rem;
  padding: 0 0.75rem;
  border-radius: 999px;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
}

.top-meta span {
  color: rgba(227, 242, 238, 0.78);
  background: rgba(95, 145, 149, 0.12);
}

.top-pills span,
.chip.gold {
  color: #f1ddb0;
  background: rgba(169, 136, 72, 0.16);
  border: 1px solid rgba(206, 175, 111, 0.18);
}

.main-stage {
  display: grid;
  grid-template-columns: minmax(13.5rem, 15.5rem) minmax(0, 1fr);
  gap: 0.875rem;
  min-width: 0;
}

.side-rail,
.primary-stage,
.footer-grid,
.draw-metrics,
.metric-pair,
.risk-grid,
.workspace-grid,
.pool-list,
.timeline-preview {
  display: grid;
  gap: 0.75rem;
}

.side-rail {
  align-content: start;
}

.primary-stage {
  min-width: 0;
  padding: 0.95rem;
  border-radius: 1.5rem;
  background: rgba(5, 13, 18, 0.58);
  border: 1px solid rgba(121, 171, 166, 0.12);
}

.rail-card,
.stage-card,
.footer-card,
.confirm-card {
  background: linear-gradient(180deg, rgba(9, 23, 29, 0.95), rgba(5, 15, 20, 0.96));
  border: 1px solid rgba(129, 174, 170, 0.16);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.rail-card {
  display: grid;
  gap: 0.75rem;
  padding: 0.95rem;
  border-radius: 1.35rem;
}

.stage-card,
.footer-card {
  display: grid;
  gap: 0.85rem;
  min-width: 0;
  padding: 1rem;
  border-radius: 1.35rem;
}

.world-card {
  background:
    linear-gradient(160deg, rgba(8, 26, 31, 0.97), rgba(5, 15, 20, 0.98)),
    radial-gradient(circle at top left, rgba(89, 157, 159, 0.16), transparent 40%);
}

.system-card,
.tree-card,
.focus-card {
  background:
    linear-gradient(180deg, rgba(10, 24, 30, 0.96), rgba(4, 14, 19, 0.98)),
    radial-gradient(circle at top right, rgba(182, 153, 88, 0.09), transparent 42%);
}

.stage-header,
.card-head,
.section-head,
.record-top,
.focus-top,
.progress-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.card-head,
.stage-header,
.section-head {
  padding-bottom: 0.65rem;
  border-bottom: 1px solid rgba(121, 167, 162, 0.12);
}

.kicker {
  display: inline-block;
  margin-bottom: 0.25rem;
  color: rgba(145, 205, 199, 0.78);
  font-size: 0.68rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

h1,
h2,
strong,
p {
  margin: 0;
}

h1 {
  font-size: clamp(1.35rem, 2.8cqi, 1.7rem);
  line-height: 1.08;
}

h2 {
  font-size: clamp(1rem, 2.2cqi, 1.2rem);
  line-height: 1.12;
}

.chip {
  color: rgba(223, 238, 235, 0.76);
  background: rgba(90, 135, 145, 0.14);
  border: 1px solid rgba(117, 172, 178, 0.16);
}

.chip.soft {
  color: rgba(233, 244, 240, 0.78);
  background: rgba(72, 110, 123, 0.18);
}

.chip.muted {
  color: rgba(220, 237, 234, 0.82);
  background: rgba(97, 136, 145, 0.14);
}

.lead,
.inline-block p,
.record-item p,
.select-row p,
.empty-copy {
  color: rgba(221, 237, 233, 0.8);
  line-height: 1.62;
  font-size: 0.82rem;
}

.metric-stack,
.preview-stack {
  display: grid;
  gap: 0.65rem;
}

.metric-row,
.metric-cell,
.inline-block,
.confirm-preview,
.record-item,
.select-row,
.focus-shell,
.pool-item,
.preview-chip {
  border: 1px solid rgba(126, 172, 167, 0.14);
  background: rgba(8, 18, 24, 0.66);
}

.metric-row,
.metric-cell {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.8rem 0.9rem;
  border-radius: 1rem;
}

.metric-cell {
  display: grid;
  gap: 0.35rem;
  align-content: start;
}

.metric-cell span,
.metric-row span,
.inline-block span,
.progress-label span,
.record-item em,
.preview-chip span,
.focus-top span,
.section-head span,
.record-top span,
.footer-grid span {
  color: rgba(175, 204, 199, 0.74);
  font-size: 0.74rem;
}

.metric-row strong,
.metric-cell strong,
.inline-block strong,
.record-top strong,
.focus-top strong,
.confirm-preview strong,
.preview-chip strong,
.footer-grid strong {
  color: #f8fbf8;
  font-weight: 700;
}

.metric-row strong,
.metric-cell strong {
  font-size: 1.15rem;
}

.inline-block,
.confirm-preview {
  display: grid;
  gap: 0.45rem;
  padding: 0.85rem 0.95rem;
  border-radius: 1rem;
}

.metric-pair,
.draw-metrics,
.risk-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.track {
  overflow: hidden;
  height: 0.48rem;
  border-radius: 999px;
  background: rgba(78, 111, 116, 0.22);
}

.track i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(218, 188, 121, 0.78), rgba(246, 232, 193, 0.98));
}

.track.teal i {
  background: linear-gradient(90deg, rgba(96, 180, 171, 0.72), rgba(145, 228, 218, 0.96));
}

.track.danger i {
  background: linear-gradient(90deg, rgba(170, 77, 72, 0.76), rgba(232, 128, 115, 0.96));
}

.progress-block,
.mini-progress {
  display: grid;
  gap: 0.55rem;
}

.focus-shell {
  display: grid;
  gap: 0.65rem;
  padding: 0.9rem;
  border-radius: 1rem;
}

.risk-grid {
  align-items: stretch;
}

.risk-grid div {
  display: grid;
  gap: 0.3rem;
  padding: 0.8rem 0.9rem;
  border-radius: 1rem;
  border: 1px solid rgba(127, 173, 168, 0.12);
  background: rgba(8, 18, 24, 0.62);
}

.tab-button,
.secondary-button,
.action-button,
.close-button {
  appearance: none;
  border: 0;
  cursor: pointer;
  transition: transform 180ms ease, box-shadow 180ms ease, opacity 180ms ease;
}

.tab-button {
  min-height: 2.25rem;
  padding: 0 0.9rem;
  border-radius: 999px;
  color: rgba(223, 238, 235, 0.76);
  background: rgba(10, 20, 27, 0.75);
  border: 1px solid rgba(120, 167, 163, 0.14);
}

.tab-button.active {
  color: #071116;
  background: linear-gradient(135deg, rgba(197, 171, 106, 0.94), rgba(241, 227, 189, 0.98));
  box-shadow: 0 0.8rem 1.8rem rgba(165, 135, 76, 0.18);
}

.sub-tabs {
  padding-top: 0.15rem;
}

.workspace-grid {
  min-width: 0;
}

.draw-grid,
.intel-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.gift-grid {
  grid-template-columns: 1.15fr 1.05fr 0.9fr;
}

.sacrifice-grid {
  grid-template-columns: 1.15fr 0.95fr;
}

.chronicle-grid {
  grid-template-columns: 1fr;
}

.full-span {
  grid-column: 1 / -1;
}

.pool-list,
.record-list {
  min-width: 0;
}

.pool-list {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.pool-item,
.record-item,
.select-row,
.preview-chip {
  padding: 0.85rem 0.95rem;
  border-radius: 1rem;
}

.pool-item {
  display: grid;
  gap: 0.35rem;
}

.record-list {
  display: grid;
  gap: 0.65rem;
}

.record-item em {
  font-style: normal;
}

.scroll-area {
  max-height: 23rem;
  overflow: auto;
  padding-right: 0.25rem;
}

.tall-scroll {
  max-height: 27rem;
}

.compact-scroll {
  max-height: 10rem;
  overflow: auto;
  padding-right: 0.25rem;
}

.select-row {
  width: 100%;
  text-align: left;
  color: inherit;
}

.select-row.selected {
  border-color: rgba(220, 190, 122, 0.42);
  background: linear-gradient(180deg, rgba(171, 136, 76, 0.2), rgba(8, 18, 25, 0.84));
  box-shadow: 0 1rem 2rem rgba(0, 0, 0, 0.18);
}

.action-card {
  align-content: start;
}

.action-stack {
  display: grid;
  gap: 0.75rem;
}

.action-button {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 0.25rem;
  min-height: 3.2rem;
  padding: 0.75rem 1rem;
  border-radius: 1rem;
  color: #0a1316;
  font-weight: 700;
  background: linear-gradient(135deg, rgba(193, 167, 104, 0.96), rgba(242, 231, 200, 0.98));
  box-shadow: 0 1rem 2rem rgba(168, 136, 74, 0.18);
}

.action-button small {
  color: rgba(15, 22, 24, 0.74);
  font-weight: 500;
}

.action-button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
  box-shadow: none;
}

.secondary-button {
  min-height: 2.65rem;
  padding: 0 0.9rem;
  border-radius: 0.9rem;
  color: rgba(223, 238, 235, 0.82);
  background: rgba(12, 24, 30, 0.92);
  border: 1px solid rgba(123, 170, 167, 0.18);
}

.timeline-preview {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.preview-chip {
  display: grid;
  gap: 0.3rem;
}

.stage-footer {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.footer-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.full-line {
  grid-column: 1 / -1;
}

.empty-copy {
  padding: 0.35rem 0 0;
}

.confirm-backdrop {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: grid;
  place-items: center;
  padding: 1rem;
  background: rgba(2, 8, 12, 0.62);
  backdrop-filter: blur(0.8rem);
}

.confirm-card {
  position: relative;
  width: min(33rem, 100%);
  display: grid;
  gap: 1rem;
  padding: 1.25rem;
  border-radius: 1.45rem;
  box-shadow: 0 1.5rem 3.75rem rgba(0, 0, 0, 0.38);
}

.close-button {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  display: grid;
  place-items: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 999px;
  color: rgba(227, 241, 238, 0.86);
  background: rgba(12, 24, 29, 0.84);
}

.tab-button:hover,
.secondary-button:hover,
.action-button:hover,
.select-row:hover,
.close-button:hover {
  transform: translateY(-1px);
}

@container (max-width: 1100px) {
  .main-stage {
    grid-template-columns: minmax(12.75rem, 14.5rem) minmax(0, 1fr);
  }

  .gift-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .gift-grid > :last-child {
    grid-column: 1 / -1;
  }

  .pool-list,
  .timeline-preview {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@container (max-width: 860px) {
  .shell {
    padding: 0.875rem;
  }

  .top-bar,
  .stage-header,
  .card-head,
  .section-head,
  .confirm-actions {
    flex-direction: column;
    align-items: flex-start;
  }

  .draw-grid,
  .gift-grid,
  .sacrifice-grid,
  .intel-grid,
  .stage-footer,
  .footer-grid,
  .pool-list,
  .timeline-preview,
  .metric-pair,
  .draw-metrics,
  .risk-grid {
    grid-template-columns: 1fr;
  }

  .top-bar {
    padding: 0.75rem;
  }

  .primary-stage,
  .rail-card,
  .stage-card,
  .footer-card {
    padding: 0.875rem;
  }
}

@container (max-width: 720px) {
  .main-stage {
    grid-template-columns: minmax(11.75rem, 13.25rem) minmax(0, 1fr);
  }

  .top-meta,
  .top-pills {
    gap: 0.375rem;
  }

  .top-meta span,
  .top-pills span,
  .chip,
  .tab-button {
    min-height: 1.8rem;
    padding: 0 0.65rem;
    font-size: 0.68rem;
  }
}

@container (max-width: 620px) {
  .main-stage {
    grid-template-columns: 1fr;
  }

  .side-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .primary-stage {
    padding-top: 0.8rem;
  }
}

@container (max-width: 560px) {
  .shell {
    padding: 0.75rem;
    border-radius: 1.4rem;
  }

  .side-rail,
  .group-tabs,
  .sub-tabs {
    grid-template-columns: 1fr;
  }

  .group-tabs,
  .sub-tabs {
    display: grid;
  }

  .confirm-card {
    padding: 1rem;
  }
}
